// Dados iniciais
let lampadas = [
  { id: 1, nome: 'Sala de Estar', ligada: false },
  { id: 2, nome: 'Quarto', ligada: true },
  { id: 3, nome: 'Cozinha', ligada: false },
];
let nextId = 4;

// Funções simuladas com Promise (como se fossem chamadas HTTP)
export const getLampadas = () => {
  return Promise.resolve([...lampadas]);
};

export const addLampada = (nome) => {
  const nova = { id: nextId++, nome, ligada: false };
  lampadas.push(nova);
  return Promise.resolve(nova);
};

export const toggleLampada = (id) => {
  const lamp = lampadas.find(l => l.id === id);
  if (lamp) {
    lamp.ligada = !lamp.ligada;
  }
  return Promise.resolve(lamp);
};

export const deleteLampada = (id) => {
  lampadas = lampadas.filter(l => l.id !== id);
  return Promise.resolve();
};
